<?php
if(!function_exists('test_guard'))throw new RuntimeException('Use isolated turnover launcher');
test_guard([envValue('DB_NAME')]);
(function()use($p,$ops,$client,$other){
 $makeUser=function($key,$shift)use($p){$id=insert($p,'users',['username'=>'selected_'.$key,'email'=>'selected_'.$key.'@example.test','full_name'=>'Selected '.$key,'password_hash'=>password_hash('Isolated-selected-only-42!',PASSWORD_DEFAULT),'role'=>'container_wingvan_dispatcher','shift'=>$shift]);return ['id'=>$id,'role'=>'container_wingvan_dispatcher','shift'=>$shift];};
 $out=$makeUser('out','Day');$in=$makeUser('in','Night');$stranger=$makeUser('stranger','Night');
 $make=function($ref,$status='In Transit')use($p,$ops,$client,$out){$id=insert($p,'trips',['trip_ref'=>'SEL-'.$ref,'created_by'=>$ops['id'],'client_id'=>$client,'truck_type'=>'Container','dispatcher_role'=>$out['role'],'dispatcher_shift'=>'Day','dispatcher_id'=>$out['id'],'pickup_point'=>'Fixture origin','delivery_point'=>'Fixture destination','scheduled_at'=>date('Y-m-d H:i:s'),'status'=>$status]);Trips::action($ops,'turnover_assign_initial',['trip_id'=>$id,'dispatcher_id'=>$out['id']]);return $id;};
 $a=$make('A');$b=$make('B');$c=$make('C');$untouched=$make('UNSELECTED');$closed=$make('CLOSED','Completed');$cancelled=$make('CANCELLED','Cancelled');$return=$make('RETURN','Completed');$v=insert($p,'vehicles',['plate_number'=>'SELECT-RETURN','truck_type'=>'Container']);run($p,'UPDATE trips SET vehicle_id=? WHERE id=?',[$v,$return]);insert($p,'trip_assignments',['trip_id'=>$return,'resource_type'=>'vehicle','resource_id'=>$v,'role'=>'vehicle']);
 $stable=[];foreach(['dispatcher_attendance_sessions','attendance_marks','trip_assignments','vehicles','personnel','fund_requests','billings','trip_updates'] as $table)$stable[$table]=many($p,'SELECT * FROM '.$table.' ORDER BY 1');
 $original=many($p,'SELECT id,dispatcher_id,dispatcher_role,dispatcher_shift FROM trips WHERE id IN ('.implode(',',[$a,$b,$c,$untouched,$closed,$cancelled,$return]).') ORDER BY id');
 $endorse=function(array $ids)use($out,$in){$review=Trips::action($out,'turnover_preview',['trip_ids'=>$ids]);return ['incoming_id'=>$in['id'],'trip_ids'=>$ids,'fingerprint'=>$review['fingerprint'],'request_key'=>turn_key()];};
 foreach([[],[$a,$a],['bad'],[true],['1 OR 1=1']] as $bad)turn_denied(fn()=>Trips::action($out,'turnover_preview',['trip_ids'=>$bad]),400,'Reject empty, duplicate or invalid selected-trip list');
 $legacy=Trips::action($out,'turnover_preview',[]);turn_denied(fn()=>Trips::action($out,'turnover_endorse',['incoming_id'=>$in['id'],'fingerprint'=>$legacy['fingerprint'],'request_key'=>turn_key()]),400,'Endorsement cannot implicitly select all work');
 foreach([$closed,$cancelled] as $id)turn_denied(fn()=>Trips::action($out,'turnover_preview',['trip_ids'=>[$id]]),409,'Closed trips are not eligible');
 $payload=$endorse([$a]);$h=Trips::action($out,'turnover_endorse',$payload)['turnover_id'];turn_ok((int)one($p,'SELECT COUNT(*) n FROM dispatcher_turnover_trips WHERE turnover_id=?',[$h])['n']===1,'Single-trip endorsement records exactly the selected reference');
 turn_ok((int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$a])['current_dispatcher_id']===$out['id'],'Selected pending trip retains outgoing responsibility');
 turn_ok(!empty(Trips::action($out,'turnover_endorse',$payload)['duplicate']),'Exact selected-set endorsement retries are idempotent');
 $changed=$payload;$changed['trip_ids']=[$b];turn_denied(fn()=>Trips::action($out,'turnover_endorse',$changed),409,'Request key cannot be reused for another selection');
 turn_denied(fn()=>Trips::action($stranger,'turnover_accept',['turnover_id'=>$h]),403,'Wrong same-group incoming account cannot accept selected work');
 turn_denied(fn()=>Trips::action($other,'turnover_accept',['turnover_id'=>$h]),403,'Cross-group acceptance denied');
 $cross=$endorse([$b]);$cross['incoming_id']=$other['id'];turn_denied(fn()=>Trips::action($out,'turnover_endorse',$cross),403,'Cross-group endorsement denied');
 $self=$endorse([$b]);$self['incoming_id']=$out['id'];turn_denied(fn()=>Trips::action($out,'turnover_endorse',$self),409,'Self endorsement denied');
 Trips::action($in,'turnover_accept',['turnover_id'=>$h]);turn_ok((int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$untouched])['current_dispatcher_id']===$out['id'],'Unselected work remains with outgoing account');
 turn_denied(fn()=>Trips::action($out,'turnover_preview',['trip_ids'=>[$a]]),409,'Outgoing cannot select work already transferred');
 $payload=$endorse([$c,$b]);$multi=Trips::action($out,'turnover_endorse',$payload)['turnover_id'];$conflict=$endorse([$b]);turn_denied(fn()=>Trips::action($out,'turnover_endorse',$conflict),409,'Overlapping pending selected trip is blocked');
 $workers=[];for($i=0;$i<2;$i++){$proc=proc_open([PHP_BINARY,__DIR__.'/turnover_concurrency_worker.php',json_encode(['user_id'=>$in['id'],'turnover_id'=>$multi])],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$workers[]=[$proc,$pipes];}$answers=[];foreach($workers as [$proc,$pipes]){$json=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);$answers[]=json_decode($json,true);turn_ok($exit===0&&$err==='','Concurrent selected-set acceptance completes');}
 turn_ok(count(array_filter($answers,fn($x)=>!empty($x['duplicate'])))===1,'Concurrent multi-trip acceptance transfers once and retries safely');
 turn_ok((int)one($p,'SELECT COUNT(*) n FROM trip_responsibilities WHERE trip_id IN (?,?) AND current_dispatcher_id=?',[$b,$c,$in['id']])['n']===2,'Acceptance transfers all and only selected trips');
 $r=Trips::action($out,'turnover_endorse',$endorse([$return]))['turnover_id'];Trips::action($in,'turnover_accept',['turnover_id'=>$r]);turn_ok((int)one($p,'SELECT current_dispatcher_id FROM trip_responsibilities WHERE trip_id=?',[$return])['current_dispatcher_id']===$in['id'],'Completed Arrival Pending trip remains eligible without releasing holds');
 $x=$make('ATOMIC-X');$y=$make('ATOMIC-Y');$atomic=Trips::action($out,'turnover_endorse',$endorse([$x,$y]))['turnover_id'];run($p,"UPDATE trips SET status='Completed' WHERE id=?",[$y]);$eventCount=(int)one($p,'SELECT COUNT(*) n FROM trip_events')['n'];turn_denied(fn()=>Trips::action($in,'turnover_accept',['turnover_id'=>$atomic]),409,'Acceptance revalidates each selected trip and rejects newly closed work');
 turn_ok((int)one($p,'SELECT COUNT(*) n FROM trip_responsibilities WHERE trip_id IN (?,?) AND current_dispatcher_id=? AND version=1',[$x,$y,$out['id']])['n']===2&&(int)one($p,'SELECT COUNT(*) n FROM trip_events')['n']===$eventCount,'Failed selected acceptance rolls back every ownership/version/event change');
 $details=Trips::action($in,'turnover_details',['turnover_id'=>$atomic]);$live=array_column($details['current_rows'],'status','id');$saved=array_column($details['rows'],'status','id');turn_ok($live[$y]==='Completed'&&$saved[$y]==='In Transit','Incoming details show current statuses alongside immutable endorsement snapshot');
 $review=Trips::action($out,'turnover_preview',['trip_ids'=>[$untouched]]);run($p,"UPDATE trips SET status='Dispatched' WHERE id=?",[$untouched]);turn_denied(fn()=>Trips::action($out,'turnover_endorse',['incoming_id'=>$in['id'],'trip_ids'=>[$untouched],'fingerprint'=>$review['fingerprint'],'request_key'=>turn_key()]),409,'Stale selected-trip review is rejected');
 turn_ok(many($p,'SELECT id,dispatcher_id,dispatcher_role,dispatcher_shift FROM trips WHERE id IN ('.implode(',',[$a,$b,$c,$untouched,$closed,$cancelled,$return]).') ORDER BY id')===$original,'Original dispatch actors and planning fields stay unchanged');
 foreach($stable as $table=>$rows)turn_ok(many($p,'SELECT * FROM '.$table.' ORDER BY 1')===$rows,'Selected turnover preserves '.$table);
 $history=Trips::action($ops,'turnover_list',[])['rows'];turn_ok((bool)array_filter($history,fn($row)=>(int)$row['id']===(int)$atomic&&$row['status']==='Pending')&&(bool)array_filter($history,fn($row)=>(int)$row['id']===(int)$multi&&$row['status']==='Accepted'),'Operations Head sees both pending and accepted selected turnovers without approval processing');
 require __DIR__.'/selected_turnover_api_tests.php';
})();
